export async function appendSignatureDetails(root,client,eventId,applicationId,isCurrent=()=>true,hasSignature=true){
 const section=document.createElement('section');section.className='applicant-signature-details';const title=document.createElement('h3'),status=document.createElement('p');title.textContent='ลายเซ็นผู้เข้าร่วม';status.className='sub';status.setAttribute('role','status');status.textContent=hasSignature?'กำลังโหลดลายเซ็น…':'ยังไม่มีลายเซ็น';section.append(title,status);root.append(section);if(!hasSignature)return;
 try{const data=await client.signCheckin({action:'view',eventId,applicationId});if(!isCurrent()||!section.isConnected)return;const image=document.createElement('img');image.className='signature-image';image.alt='ลายเซ็นของ '+data.signerName;image.src=data.signaturePng;status.textContent='ผู้ลงลายเซ็น: '+data.signerName+(data.recordedAtMs?' · บันทึก '+new Date(data.recordedAtMs).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'');section.append(image)}catch(error){if(isCurrent()&&section.isConnected)status.textContent=error.message||'โหลดลายเซ็นไม่ได้ กรุณาปิดแล้วเปิดรายละเอียดใหม่'}
}
